public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    ArrayList<Integer> Q = new ArrayList<>();
    ArrayList<Integer> A = new ArrayList<>();
    ArrayList<Integer> B = new ArrayList<>();

    for (int i = 0; i < N; i++) Q.add(sc.nextInt());
    for (int i = 0; i < N; i++) A.add(sc.nextInt());
    for (int i = 0; i < N; i++) B.add(sc.nextInt());

    int MAX_NUM = 0;
    for (int aServings = 0; ; aServings++) {
        boolean canMakeA = true;
        for (int i = 0; i < N; i++) {
            if (A.get(i) * aServings > Q.get(i)) {
                canMakeA = false;
                break;
            }
        }
        if (!canMakeA) break;

        int bServings = Integer.MAX_VALUE;
        for (int i = 0; i < N; i++) {
            if (B.get(i) > 0) {
                bServings = Math.min(bServings, (Q.get(i) - A.get(i) * aServings) / B.get(i));
            }
        }
        if (bServings == Integer.MAX_VALUE) bServings = 0;

        MAX_NUM = Math.max(MAX_NUM, aServings + bServings);
    }
    System.out.println(MAX_NUM);
}
